const e={ocnal:{baipishu:"Белая книга",home1:"Откройте мир цифровых валют",home2:"Пополнить сейчас",home3:"Имя",home4:"Цена",home5:"Изменение за 24 часа",home6:"Торговля",home7:"Начать",home8:"Создать аккаунт",home9:"Зарегистрируйтесь, чтобы получить больше преимуществ и услуг",home10:"Регистрация",home11:"Пополнить счёт",home12:"Пополните свой счёт и начните инвестировать в криптовалюты",home13:"Пополнить крипто",home14:"Начать торговлю",home15:"Продавайте, покупайте или копируйте сделки — откройте больше возможностей",home16:"Изучить рынок",home17:"Рынок криптовалют стремительно развивается, включая цифровые валюты, блокчейн и многое другое. Перспективы велики, но инвестиции требуют осторожности.",home18:"Спот",home19:"Реальная торговля на спотовом рынке с быстрыми изменениями цен.",home20:"Бессрочный контракт",home21:"Контрактная торговля предоставляет кредитное плечо и позволяет получать высокую прибыль.",home22:"Опционы",home23:"Опционная торговля предлагает гибкие стратегии хеджирования для контроля рисков и получения дохода.",home24:"AI-инвестиции",home25:"Планируйте с уверенностью. Инвестируйте разумно. Меньше беспокойтесь.",home26:"Самая высокая годовая доходность в истории",home27:"Текущий",home28:"Фиксированный",home29:"Купить сейчас",home30:"Каждый может использовать цифровую валюту",home31:"От первого опыта торговли криптовалютой до первой покупки финансового продукта — платформа поможет вам легко зарабатывать монеты.",home32:"Узнайте о криптовалюте",home33:"Изучите всё о криптовалютах и начните инвестировать",home34:"Часто задаваемые вопросы",home35:"Готовы начать своё крипто-путешествие?",home36:"Что такое криптовалютная биржа?",home37:"Криптовалютные биржи — это цифровые площадки, где пользователи могут покупать и продавать криптовалюты, такие как Bitcoin, Ethereum и Tether. Binance — крупнейшая биржа по объёму торгов.",home38:"Какие продукты предлагает платформа?",home39:"Как ведущая мировая криптобиржа, она обслуживает более 150 миллионов пользователей из 180 стран. С низкими комиссиями она предлагает свыше 350 торгуемых криптовалют.<br><br>На платформе пользователи могут:<br><br>1. Торговать сотнями валют и торговых пар.<br><br>2. Покупать и продавать криптовалюты через спотовую торговлю.<br><br>3. Зарабатывать проценты через управление активами.",home40:"Как торговать криптовалютами на платформе",home41:"На платформе вы можете торговать сотнями криптовалют на спотовом, фьючерсном и опционном рынках. Зарегистрируйтесь, подтвердите личность и внесите депозит, чтобы начать.",home42:"Безопасна ли эта платформа?",home43:"Платформа обеспечивает безопасную и надёжную торговлю. Мы используем передовые технологии безопасности и профессиональную команду. Все активы пользователей полностью подтверждены в соотношении 1:1.",home44:"Как восстановить забытый пароль?",home45:"Нажмите «Забыли пароль?» на странице входа и сбросьте его.",home46:"Зачем нужна идентификация личности?",home47:"Чтобы защитить ваши средства и предотвратить отмывание денег, мы должны убедиться, что ваш счёт связан с вашими личными данными.",home48:"Рынки",home49:"Глобальный рынок торговли криптовалютами поддерживает многовалютные операции, обеспечивая безопасность и эффективность.",home50:"Мой аккаунт",home51:"Пополнить",home52:"Вывести",home53:"Конвертировать",home54:"Популярное",home55:"Инвестируйте в недавно выпущенные токены и получите высокий потенциал доходности",home56:"Новости",home57:"Почему выбирают нас?",home58:"Нам доверяют миллионы пользователей",home59:"Количество пользователей",home60:"Партнёрская организация",home61:"Минимальные комиссии за транзакции",home62:"Партнёры",home63:"Объём за 24 часа",home64:"Откройте новую эру цифрового богатства",home65:"Безопасная торговля, простое инвестирование",home66:"Начать сейчас",home67:"Умная торговля, связь с будущим",home68:"Молниеносная торговля, не упустите движение",home69:"Цифровые активы на расстоянии одного касания",jianguanzhengshu:"Регуляторный сертификат",falvzhengmingshu:"Юридический сертификат",withdrawNote:"Уведомление о выводе:<br><br>Время обработки вывода составляет 24 часа<br><br>После подачи заявки на вывод средства будут заморожены, поскольку вывод находится в обработке и временно хранится системой. Это не означает, что ваши активы потеряны или есть какая-либо аномалия.<br><br>Заявки на вывод токенов будут зачислены в течение 12 часов после подачи. Если вывод токенов не поступил после ожидаемого времени, обратитесь в онлайн-службу поддержки.<br><br>Крупные выводы доступны только нашим VIP-членам. Подробности узнайте у онлайн-службы поддержки."},yingshe:{miaoheyue:"Опционная торговля",miaoheyuejiaoyi:"Опционная торговля",heyuezhanghu:"Торговый счет"},deltax:{company_bylaws:"Устав компании",good_standing_certificate:"Справка о хорошей репутации",about_title:"О нас",about_text_1:"Мы — одна из самых быстрорастущих торговых платформ в Европе, с офисами в Великобритании, Европе и Австралии. Мы всегда ставим клиента в центр каждого решения, способствуя его торговле через интуитивные технологии, углубленное образование и всестороннюю поддержку.",about_text_2:"Наша миссия — предоставить трейдерам инструменты и ресурсы, необходимые для уверенной торговли и принятия более правильных решений. Эта миссия принесла нам множество наград от ведущих отраслевых авторитетов.",stats_title:"Обзор роста",stat_global_label:"Глобальная деятельность",stat_global_desc:"По мере увеличения числа наших глобальных офисов мы гордимся обслуживанием клиентов в 183 странах и регионах",stat_global_link:"Узнать о торговле",stat_traders_label:"Трейдеры",stat_traders_desc:"С момента запуска наше глобальное сообщество трейдеров совершило сделок на сумму более 53 млрд долларов США",stat_traders_link:"Последние новости",stat_support_label:"Сотрудники поддержки",stat_support_desc:"Наша дружелюбная служба поддержки работает круглосуточно на 12 языках, чтобы помочь вам с любыми вопросами, связанными со счетом",stat_support_link:"Поддержка",promise_title:"Наше обязательство перед клиентами",promise_desc:"Торговля — это навык, которым владеют немногие. Но мы верим, что, правильно сочетая инновационные технологии, погружение в обучение и уникальное понимание торгового поведения, любой может развить торговую экспертизу на рынках. Независимо от того, опытный вы трейдер или новичок, мы предоставляем инструменты, необходимые для повышения знаний и навыков.",promise_customer_name:"Клиент на первом месте",promise_customer_text:"Созданная трейдерами, мы применяем специализированные исследования, науку о данных и уникальные инсайты для разработки продуктов, которые вдохновляют наших клиентов на рост",promise_innovation_name:"Никогда не останавливаемся",promise_innovation_text:"Мы стремимся непрерывно оптимизировать нашу платформу, обеспечивая бесперебойный пользовательский опыт и уверенную торговлю с лучшими решениями с помощью инновационных инструментов, в которых технологии на первом месте",promise_transparency_name:"Всегда прозрачны",promise_transparency_text:"Мы стремимся снимать барьеры для торговли, предлагая одни из самых конкурентных цен в отрасли, а также удобные и обширные образовательные ресурсы",promise_expertise_name:"Экспертность превыше всего",promise_expertise_text:"Наша международная команда обладает многолетним опытом в торговых технологиях и экспертизе, закладывая основу для удобной, технологичной и интуитивной платформы",expertise_title:"Наша экспертиза",expertise_text_1:"Как отмеченный наградами брокер, мы признаны клиентами за технологичный, интуитивно понятный пользовательский опыт, высококачественную поддержку и отличное соотношение цены и качества. Технологии — в основе всего, что мы делаем: мы предлагаем умные функции, такие как данные рынка в реальном времени, продвинутые инструменты графиков и адаптивные мобильные приложения для торговли на ходу. Наша цель — предоставить розничным трейдерам беспрепятственный доступ к глобальным финансовым инструментам.",expertise_text_2:"Мы постоянно ищем новые способы помочь клиентам торговать уверенно и принимать более разумные решения, предоставляя новейшие технологии, углубленные образовательные ресурсы и конкурентные цены в постоянно меняющейся торговой среде.",expertise_stat_traders:"Трейдеры",expertise_stat_service:"Служба поддержки",expertise_stat_unit_second:"с",expertise_stat_speed_label:"Средняя скорость исполнения",expertise_stat_indicators:"Технические индикаторы",expertise_footnote:"На основе наших внутренних данных серверов за 2022 год",awards_title:"Признание отрасли",awards_desc_1:"Наши интуитивные продукты, преданная служба поддержки и постоянные инновации неоднократно получали признание ведущих авторитетов отрасли.",awards_desc_2:"В 2023 году Deloitte Technology Fast 50 включил нас в число 50 самых быстрорастущих технологических компаний на Ближнем Востоке и в Кипре. Вот некоторые из наших недавних наград:",products_title:"Наши продукты и услуги",product_cfd_name:"Торговля CFD",product_cfd_desc:"Открывайте длинные и короткие позиции по форекс, индексам, акциям, товарам и многому другому, без фиксированной даты экспирации и без налога на биржевые операции с британскими акциями",product_platform_name:"Удобная платформа",product_platform_desc:"Мы уделяем первостепенное внимание удобству для клиентов, обеспечивая торговлю через десктоп, мобильные устройства и API",product_demo_name:"Демо-счет",product_demo_desc:"Трейдеры могут без риска протестировать нашу платформу на виртуальных средствах, одновременно совершенствуя свои торговые стратегии",product_education_name:"Обучение",product_education_desc:"Предоставляет углубленный анализ последних фундаментальных и технических драйверов рынка, чтобы помочь трейдерам принимать обоснованные решения",product_more:"Подробнее",products_footnote:"Налоговое обращение зависит от индивидуальных обстоятельств и может меняться или отличаться в юрисдикциях за пределами Великобритании",global_title:"Глобальные офисы",award_source_good_money:"Good Money Guide",award_source_online_money:"Online Money Awards",award_source_forexbrokers:"ForexBrokers.com",award_source_investment_trends:"Investment Trends",award_source_advfn:"ADVFN",award_source_ft:"Financial Times Investors’ Chronicle",award_good_money_guide:"Лучшее торговое приложение 2023",award_online_money:"Лучший CFD-провайдер 2023",award_forexbrokers:"Самый быстрорастущий брокер 2023",award_investment_satisfaction:"Общая удовлетворенность клиентов 2022",award_investment_value:"Лучшее соотношение цены и качества 2022",award_advfn:"Самый быстрорастущий брокер 2023",award_ft_investors:"Поддержка новых инвесторов 2022"},licai:{zhiyawakuang:"Умный доход",zhiyawakuangjiaoyi:"Торговля умным доходом"}};export{e as default};
